            for (let i = 0; i < n; i++) {
              const a0 = i / n * Math.PI * 2;
              const a1 = (i + 1) / n * Math.PI * 2;
              buf.tri(P(0, cy, zf), at(a0, r2 * 0.78), at(a1, r2 * 0.78), glass);
              buf.tri(at(a0, r2 * 0.78), at(a0, r2), at(a1, r2), col2);
              buf.tri(at(a0, r2 * 0.78), at(a1, r2), at(a1, r2 * 0.78), col2);
              buf.tri(at(a0, r2), at(a0, r2 * 1.18), at(a1, r2 * 1.18), col2, dark, dark);
              buf.tri(at(a0, r2), at(a1, r2 * 1.18), at(a1, r2), col2, dark, col2);
            }
